"""
Tutor plugin: ost2_lil_stranger   (OST2)

Serves the Li'l Stranger mascot "says hello" page on the LMS:

    https://<LMS_HOST>/lil-stranger/                 (public, no login)
    https://<LMS_HOST>/lil-stranger/hello.webp
    https://<LMS_HOST>/lil-stranger/telescope.webp   (used by the site footers)

Every Li'l Stranger image on the site (Progress tab, Timing Feedback nudge, gamma dashboard,
leaderboards, footer telescope) links here. Same mechanism as ost2_report_missing_accomplishments:
injected into the LMS production settings and mounted on the root urlconf on first request,
so it needs only `tutor config save` + `tutor local restart lms` -- NO image rebuild.
Images are embedded (base64) so the plugin is self-contained.

Deploy:
    cp ost2_lil_stranger.py "$(tutor plugins printroot)"/
    tutor plugins enable ost2_lil_stranger
    tutor config save && tutor local restart lms
"""
from tutor import hooks

__version__ = "1.0.0"

_HELLO_B64 = ""
_TELESCOPE_B64 = ""

_CODE = '''
# ============================================================================
# OST2: Li'l Stranger "says hello" page. Injected by the ost2_lil_stranger tutor plugin.
# ============================================================================
import base64 as _ost2_ls_b64
import logging as _ost2_ls_logging

_ost2_ls_log = _ost2_ls_logging.getLogger("ost2.lil_stranger")

_OST2_LS_IMAGES = {
    "hello.webp": _ost2_ls_b64.b64decode("@@HELLO_B64@@"),
    "telescope.webp": _ost2_ls_b64.b64decode("@@TELESCOPE_B64@@"),
}

_OST2_LS_CSS = (
    ":root{--bg:#fff;--fg:#1f2937}"
    "@media (prefers-color-scheme: dark){:root{--bg:#111827;--fg:#e5e7eb}}"
    "body{margin:0;background:var(--bg);color:var(--fg);font:18px/1.6 Inter,system-ui,-apple-system,Segoe UI,Roboto,sans-serif}"
    "main{max-width:760px;margin:0 auto;padding:32px 16px;text-align:center}"
    "h1{font-size:2.5rem;line-height:1.2;margin:0 0 1rem}"
    "img{max-width:100%;height:auto;max-height:70vh}"
    "p{margin:1rem 0 0}"
)


def _ost2_ls_page_view(request):
    from django.http import HttpResponse
    html = (
        '<!doctype html><html lang="en"><head><meta charset="utf-8">'
        '<meta name="viewport" content="width=device-width, initial-scale=1">'
        '<meta name="color-scheme" content="light dark">'
        '<title>Li&#39;l Stranger says hello!</title><style>' + _OST2_LS_CSS + '</style></head>'
        '<body><main>'
        '<h1>Li&#39;l Stranger says hello!</h1>'
        '<img src="/lil-stranger/hello.webp" alt="Hello from Li&#39;l Stranger">'
        '<p>Hi! I&#39;m Li&#39;l Stranger! I&#39;m the new OST2 mascot! I&#39;ll just be fiddling around in the '
        'background on the site. Remember, just because you don&#39;t see me doesn&#39;t mean I&#39;m not there ;)</p>'
        '</main></body></html>'
    )
    return HttpResponse(html)


def _ost2_ls_image_view(request, name):
    from django.http import HttpResponse, Http404
    data = _OST2_LS_IMAGES.get(name)
    if data is None:
        raise Http404
    resp = HttpResponse(data, content_type="image/webp")
    resp["Cache-Control"] = "public, max-age=86400"
    return resp


def _ost2_ls_install():
    import importlib
    from django.urls import re_path
    from django.conf import settings
    urls = importlib.import_module(settings.ROOT_URLCONF)
    if getattr(urls, "_ost2_ls_installed", False):
        return
    urls.urlpatterns.insert(0, re_path(r"^lil-stranger/(?P<name>hello\\.webp|telescope\\.webp)$", _ost2_ls_image_view, name="ost2_lil_stranger_image"))
    urls.urlpatterns.insert(0, re_path(r"^lil-stranger/$", _ost2_ls_page_view, name="ost2_lil_stranger"))
    urls._ost2_ls_installed = True
    _ost2_ls_log.info("ost2 lil-stranger page installed")


from django.core.signals import request_started as _ost2_ls_req
from django.dispatch import receiver as _ost2_ls_receiver


@_ost2_ls_receiver(_ost2_ls_req, dispatch_uid="ost2_lil_stranger_install")
def _ost2_ls_boot(sender, **kwargs):
    try:
        _ost2_ls_install()
    except Exception:
        _ost2_ls_log.exception("ost2 lil-stranger: install failed")
'''.replace("@@HELLO_B64@@", _HELLO_B64).replace("@@TELESCOPE_B64@@", _TELESCOPE_B64)

hooks.Filters.ENV_PATCHES.add_item(("openedx-lms-production-settings", _CODE))
